#include <bits/stdc++.h>
using namespace std;

 void TT() { 
      
       
      int N ; 
        cin >> N ; 
          int M =  3*N ; 
            vector<int>A(M) ; 
              for(int i=0;i<M;i++) {
                    cin >> A[i] ;
              }
               sort(A.begin(),A.end()) ; 
                    reverse(A.begin(),A.end()) ; 
                   vector<long long>X(2*M,0) ; 
                     for(int i=1;i<=M;i++) {
                          X[i] = X[i-1]+A[i-1] ;
                     }
                        long long ANS =0LL ; 
                         
                          for(int  i=0;i<=N;i++) {
                                long long L = 0 , R = N-i ;
                                  while(L<R) {
                                        int MD = (L+(R-L)/2) ;
                                         long long Y = 2LL*(X[i])+X[i+2LL*(MD+1)]+3LL*X[M-2*i-(MD+1)]  ;
                                              long long Z= 2LL*(X[i])+X[i+2LL*(MD)]+3LL*X[M-2*i-(MD)]  ;
                                                if(Y>Z) {
                                                     L= MD+1 ;
                                                } else {
                                                          R = MD ;
                                                }
                                  }
                                    ANS = max(2LL*(X[i])+X[i+2LL*(L)]+3LL*X[M-2*i-(L)] ,ANS) ;
                          }
                          
                           cout << ANS << endl ;
 }

int main() {
    
       int T ; 
         cin >> T ; 
            while(T--) {
                  TT() ;
            }


  return 0 ;
}
